//Generated by AI

using UnityEngine;
using System.Collections;

public class TutorialTrigger : MonoBehaviour
{
    [Header("Tutorial Settings")]
    [SerializeField] private UIButtonHighlight[] buttonHighlights;
    [SerializeField] private string tutorialMessage;

    [Header("Accessibility")]
    [SerializeField] private SubtitleController subtitleController;

    [Header("Audio")]
    [SerializeField] private AudioSource triggerSound;

    private bool activated = false;

    private void OnTriggerEnter2D(Collider2D other)
    {
        TryActivateTutorial(other);
    }

    private void OnTriggerStay2D(Collider2D other)
    {
        TryActivateTutorial(other);
    }

    private void TryActivateTutorial(Collider2D other)
    {
        // Ensure the game has started and the trigger is not already activated.
        if (!PauseMenuController.GameStarted || activated)
            return;

        // Only the player can activate the tutorial trigger.
        if (!other.CompareTag("Player"))
            return;

        activated = true;

        if (triggerSound != null)
        {
            triggerSound.Play();
        }

        if (subtitleController != null)
        {
            subtitleController.ShowSubtitle(tutorialMessage);
        }

        // Start the highlight effect on each assigned button.
        if (buttonHighlights != null && buttonHighlights.Length > 0)
        {
            foreach (UIButtonHighlight button in buttonHighlights)
            {
                if (button != null)
                {
                    button.StartHighlight();
                }
            }

            StartCoroutine(StopHighlight());
        }
    }

    private IEnumerator StopHighlight()
    {
        // Keep the highlight active for four seconds.
        yield return new WaitForSeconds(4f);

        if (buttonHighlights != null && buttonHighlights.Length > 0)
        {
            foreach (UIButtonHighlight button in buttonHighlights)
            {
                if (button != null)
                {
                    button.StopHighlight();
                }
            }
        }

        // Disable the trigger after the highlight sequence.
        gameObject.SetActive(false);
    }
}
